test("Código de almacén: se exige el estándar de empresa (ciudad + 2 dígitos)", () => {
  for (const almacen of ["LPZ01", "SCZ12", "CIJ99"]) {
    assert.equal(registrarMovimiento([], { tipo: "ingreso", articulo: "A1", almacen, cantidad: 1 }).length, 1);
  }
  for (const almacen of ["LPZ", "lpz01", "LPZ-01", "LPZ1", "LPZ001", "XXX01", "Central La Paz", " LPZ01", 5]) {
    assert.throws(() => registrarMovimiento([], { tipo: "ingreso", articulo: "A1", almacen, cantidad: 1 }), /almacén/i);
  }
});
